-- CTX001 fictional, rollback-only. No public network retrieval or provider requests.
RESET ROLE;
SELECT ok((SELECT NOT enabled FROM firstten_private.public_context_policy WHERE singleton),'CTX001 retrieval defaults off');
SELECT ok(NOT has_table_privilege('authenticated','firstten_private.public_context_previews','SELECT,INSERT,UPDATE,DELETE'),'CTX001 browser cannot forge retrieval stamps');
SELECT ok(NOT has_table_privilege('service_role','firstten_private.public_context_policy','SELECT,INSERT,UPDATE,DELETE'),'CTX001 service cannot self-enable outbound retrieval');
SELECT ok(NOT has_function_privilege('authenticated','public.complete_public_context_retrieval(uuid,uuid,jsonb)','EXECUTE'),'CTX001 browser cannot complete a fabricated fetch');
SELECT ok(NOT has_function_privilege('authenticated','public.begin_public_context_retrieval(uuid,uuid,uuid,text,text)','EXECUTE'),'CTX001 browser cannot bypass server outbound policy');
SELECT ok(NOT has_function_privilege('service_role','public.review_public_context(uuid,uuid,text,text,text,boolean)','EXECUTE'),'CTX001 service cannot impersonate owner review');
SELECT ok(NOT has_function_privilege('anon','public.list_public_context(uuid)','EXECUTE'),'CTX001 anonymous cannot read private previews');
INSERT INTO public.projects(id,user_id,name) VALUES('fa190000-0000-4000-8000-000000000001',firstten_policy_test.id('owner_a'),'Fictional public context'),('fa190000-0000-4000-8000-000000000002',firstten_policy_test.id('owner_a'),'Separate owner idea');
CREATE TABLE firstten_policy_test.ctx_docs(label text PRIMARY KEY,doc jsonb);
GRANT SELECT,INSERT ON firstten_policy_test.ctx_docs TO authenticated,service_role;
GRANT SELECT ON firstten_policy_test.ids TO service_role;
INSERT INTO firstten_policy_test.ctx_docs VALUES('payload',jsonb_build_array(jsonb_build_object('url','https://product.example.org/','title','Fictional public page','format','plain_text','contentHash',repeat('a',64),'previewHash',encode(sha256(convert_to('Public author claim. Not customer evidence.','UTF8')),'hex'),'text','Public author claim. Not customer evidence.','bytes',42,'commitSha',NULL,'path',NULL,'blobSha',NULL)));
SET LOCAL ROLE service_role;
SELECT is(public.begin_public_context_retrieval(firstten_policy_test.id('owner_a'),'fa190000-0000-4000-8000-000000000001','fa190000-0000-4000-8000-000000000101','website',repeat('a',64))->>'code','DISABLED','CTX001 disabled before explicit operator runtime review');
RESET ROLE;
SELECT throws_ok($$UPDATE firstten_private.public_context_policy SET enabled=true$$,'23514',NULL,'CTX001 cannot enable without recorded runtime review');
UPDATE firstten_private.public_context_policy SET enabled=true,runtime_review_sha256=repeat('a',64),operator_reference='ctx001-local-fictional-only';
SET LOCAL ROLE service_role;
INSERT INTO firstten_policy_test.ctx_docs SELECT 'begin',public.begin_public_context_retrieval(firstten_policy_test.id('owner_a'),'fa190000-0000-4000-8000-000000000001','fa190000-0000-4000-8000-000000000101','website',repeat('a',64));
SELECT is((SELECT doc->>'ok' FROM firstten_policy_test.ctx_docs WHERE label='begin'),'true','CTX001 one acknowledged lease authorizes public retrieval');
SELECT is(public.begin_public_context_retrieval(firstten_policy_test.id('owner_a'),'fa190000-0000-4000-8000-000000000001','fa190000-0000-4000-8000-000000000101','website',repeat('a',64))->>'code','ALREADY_STARTED','CTX001 duplicate delivery never authorizes another fetch');
SELECT is(public.begin_public_context_retrieval(firstten_policy_test.id('owner_a'),'fa190000-0000-4000-8000-000000000001','fa190000-0000-4000-8000-000000000101','website',repeat('b',64))->>'code','CHANGED','CTX001 changed payload cannot reuse stable intent');
SELECT is(public.begin_public_context_retrieval(firstten_policy_test.id('owner_a'),'fa190000-0000-4000-8000-000000000002','fa190000-0000-4000-8000-000000000102','website',repeat('a',64))->>'code','RATE_LIMIT','CTX001 active actor lease is shared across ideas');
SELECT is(public.complete_public_context_retrieval('fa190000-0000-4000-8000-000000000101',gen_random_uuid(),(SELECT doc FROM firstten_policy_test.ctx_docs WHERE label='payload'))->>'code','EXPIRED','CTX001 wrong attempt cannot complete a lease');
SELECT is(public.complete_public_context_retrieval('fa190000-0000-4000-8000-000000000101',(SELECT (doc->>'attemptId')::uuid FROM firstten_policy_test.ctx_docs WHERE label='begin'),jsonb_set((SELECT doc FROM firstten_policy_test.ctx_docs WHERE label='payload'),'{0,retrievedAt}','"1900-01-01"'))->>'code','UNSAFE_SOURCE','CTX001 forged retrieval time is not accepted');
SELECT is(public.complete_public_context_retrieval('fa190000-0000-4000-8000-000000000101',(SELECT (doc->>'attemptId')::uuid FROM firstten_policy_test.ctx_docs WHERE label='begin'),jsonb_set((SELECT doc FROM firstten_policy_test.ctx_docs WHERE label='payload'),'{0,previewHash}',to_jsonb(repeat('b',64))))->>'code','UNSAFE_SOURCE','CTX001 excerpt hash must match literal preview');
SELECT is(public.complete_public_context_retrieval('fa190000-0000-4000-8000-000000000101',(SELECT (doc->>'attemptId')::uuid FROM firstten_policy_test.ctx_docs WHERE label='begin'),(SELECT doc FROM firstten_policy_test.ctx_docs WHERE label='payload'))->>'ok','true','CTX001 service completes bounded successful preview');
SELECT is(public.complete_public_context_retrieval('fa190000-0000-4000-8000-000000000101',(SELECT (doc->>'attemptId')::uuid FROM firstten_policy_test.ctx_docs WHERE label='begin'),(SELECT doc FROM firstten_policy_test.ctx_docs WHERE label='payload'))->>'code','EXPIRED','CTX001 completed attempt cannot insert duplicates');
RESET ROLE;
SELECT is((SELECT count(*) FROM firstten_private.public_context_previews WHERE operation_id='fa190000-0000-4000-8000-000000000101'),1::bigint,'CTX001 single preview record');
INSERT INTO firstten_policy_test.ctx_docs SELECT 'preview',jsonb_build_object('id',id,'hash',source->>'previewHash') FROM firstten_private.public_context_previews WHERE operation_id='fa190000-0000-4000-8000-000000000101';
SELECT firstten_policy_test.set_actor('owner_a');SET LOCAL ROLE authenticated;
SELECT is(jsonb_array_length(public.list_public_context('fa190000-0000-4000-8000-000000000001')->'previews'),1,'CTX001 owner previews retrieved but unreviewed content');
SELECT is(jsonb_array_length(public.list_public_context('fa190000-0000-4000-8000-000000000001')->'reviewed'),0,'CTX001 retrieval never fabricates review');
SELECT is(public.review_public_context('fa190000-0000-4000-8000-000000000001',(SELECT (doc->>'id')::uuid FROM firstten_policy_test.ctx_docs WHERE label='preview'),(SELECT doc->>'hash' FROM firstten_policy_test.ctx_docs WHERE label='preview'),'Public claim','Public author claim.',false)->>'code','INVALID_INPUT','CTX001 storage permission must be explicit');
SELECT is(public.review_public_context('fa190000-0000-4000-8000-000000000001',(SELECT (doc->>'id')::uuid FROM firstten_policy_test.ctx_docs WHERE label='preview'),repeat('b',64),'Public claim','Public author claim.',true)->>'code','CHANGED','CTX001 review binds expected source hash');
SELECT is(public.review_public_context('fa190000-0000-4000-8000-000000000001',(SELECT (doc->>'id')::uuid FROM firstten_policy_test.ctx_docs WHERE label='preview'),(SELECT doc->>'hash' FROM firstten_policy_test.ctx_docs WHERE label='preview'),'Public claim','Invented replacement text',true)->>'code','INVALID_INPUT','CTX001 edits cannot masquerade as retrieved excerpts');
SELECT is(public.review_public_context('fa190000-0000-4000-8000-000000000002',(SELECT (doc->>'id')::uuid FROM firstten_policy_test.ctx_docs WHERE label='preview'),(SELECT doc->>'hash' FROM firstten_policy_test.ctx_docs WHERE label='preview'),'Public claim','Public author claim.',true)->>'code','NOT_FOUND','CTX001 same-owner foreign idea cannot adopt preview');
INSERT INTO firstten_policy_test.ctx_docs SELECT 'review',public.review_public_context('fa190000-0000-4000-8000-000000000001',(SELECT (doc->>'id')::uuid FROM firstten_policy_test.ctx_docs WHERE label='preview'),(SELECT doc->>'hash' FROM firstten_policy_test.ctx_docs WHERE label='preview'),'Public claim','Public author claim.',true);
SELECT is((SELECT doc#>>'{source,aiPermission}' FROM firstten_policy_test.ctx_docs WHERE label='review'),'unknown','CTX001 owner review does not authorize AI');
SELECT is((SELECT doc#>>'{source,sharingPermission}' FROM firstten_policy_test.ctx_docs WHERE label='review'),'unknown','CTX001 owner review does not authorize sharing');
SELECT is(public.review_public_context('fa190000-0000-4000-8000-000000000001',(SELECT (doc->>'id')::uuid FROM firstten_policy_test.ctx_docs WHERE label='preview'),(SELECT doc->>'hash' FROM firstten_policy_test.ctx_docs WHERE label='preview'),'Public claim','Public author claim.',true),(SELECT doc FROM firstten_policy_test.ctx_docs WHERE label='review'),'CTX001 repeated review is one immutable version');
SELECT is(public.review_public_context('fa190000-0000-4000-8000-000000000001',(SELECT (doc->>'id')::uuid FROM firstten_policy_test.ctx_docs WHERE label='preview'),(SELECT doc->>'hash' FROM firstten_policy_test.ctx_docs WHERE label='preview'),'Different label','Public author claim.',true)->>'code','CHANGED','CTX001 changing a reviewed source needs a new version');
RESET ROLE;
DO $$DECLARE who text; BEGIN FOREACH who IN ARRAY ARRAY['owner_b','editor','viewer','student','teacher','admin'] LOOP PERFORM firstten_policy_test.set_actor(who); EXECUTE 'SET LOCAL ROLE authenticated'; INSERT INTO firstten_policy_test.ctx_docs VALUES(who,public.list_public_context('fa190000-0000-4000-8000-000000000001')); EXECUTE 'RESET ROLE'; END LOOP; END $$;
SELECT ok((SELECT bool_and(doc->>'code'='NOT_FOUND') FROM firstten_policy_test.ctx_docs WHERE label IN ('owner_b','editor','viewer','student','teacher','admin')),'CTX001 class/collaboration/admin markers never authorize private public-source records');
