SELECT ok((SELECT doc::text NOT LIKE '%Public author claim%' FROM firstten_policy_test.ctx_docs WHERE label='withdraw'),'CTX001 withdrawn DTO reveals no excerpt or source URL');
SELECT ok(public.list_public_context('fa190000-0000-4000-8000-000000000001')::text NOT LIKE '%Public author claim%','CTX001 current list hides withdrawn source contents');
